const pair = (en, my) => [en, my];
const group = (en, my, exercises) => ({ title: pair(en, my), exercises });
const test = (en, my, expression) => ({ label: pair(en, my), expression });
const sql = (en, my, query) => ({ label: pair(en, my), ...query });
const task = (id, title, lesson, instruction, hint, starter, solution, checks, extra = {}) =>
  ({ id, title, lesson, task: instruction, hint, starter, solution, checks, ...extra });
const p = pair;

